.mail-preview[data-preview-highlight] mark:not(.invalid) {
  background: var(--preview-highlight-background);
  color: var(--preview-highlight-text);
}
/* Keep swatches independent of the workspace’s generic selected controls. */
html
  .preview-highlight-picker
  .preview-highlight-menu
  button[data-preview-highlight][role="menuitemradio"] {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 50%;
  background: var(--preview-highlight-background);
  color: var(--preview-highlight-text);
  cursor: pointer;
}
html
  .preview-highlight-picker
  .preview-highlight-menu
  button[data-preview-highlight][role="menuitemradio"][aria-checked="true"] {
  border-color: currentColor;
}
.preview-highlight-menu button:focus-visible,
.preview-highlight-trigger:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}

.preview-highlight-upgrade p {
  margin: 8px 0;
}
